def gen(rng):
    def fmt(k, a):
        return f"{len(a)} {k}\n" + ' '.join(map(str, a))
    tests = [fmt(1, [7]), fmt(1, [1, 5, 9]), fmt(2, [1, 2]), fmt(2, [1, 3]), fmt(3, [1, 2, 3, 3, 4, 5]),
             fmt(3, [1, 2, 3, 4]), fmt(2, [5, 5, 6, 6]), fmt(4, [1, 2, 3, 4]), fmt(2, [1, 1, 2, 2, 3, 3]),
             fmt(3, [3, 2, 1, 2, 3, 4, 3, 4, 5, 9, 10, 11])]
    for _ in range(60):
        k = rng.randint(1, 4)
        if rng.random() < 0.55:
            groups = rng.randint(1, 4)
            a = []
            for _ in range(groups):
                s = rng.randint(1, 8)
                a += list(range(s, s + k))
            if rng.random() < 0.4:
                i = rng.randrange(len(a))
                a[i] += rng.choice([-1, 1, 2])
            rng.shuffle(a)
        else:
            a = [rng.randint(1, 6) for _ in range(rng.randint(1, 10))]
        tests.append(fmt(k, a))
    N = 100000
    def big(k, bad):
        g = N // k
        a = []
        for _ in range(g):
            s = rng.randint(1, 10**9 - k)
            a += list(range(s, s + k))
        if bad:
            a[rng.randrange(len(a))] = 10**9
        rng.shuffle(a)
        return fmt(k, a)
    tests.append(big(1, False))
    tests.append(big(5, False))
    tests.append(big(2, True))
    tests.append(big(100, False))
    tests.append(big(1000, True))
    tests.append(fmt(50000, list(range(1, 50001)) * 2))
    tests.append(fmt(2, [rng.randint(1, 10**9) for _ in range(N)]))
    return tests
